/*
  Assignments for the 29 test cases: 405 team assignments and 1257 individual ones.
  Generated by models/hospital/assignments_to_sql.py (rules in its docstring). Run after the test cases' specs, process.sql and
  job_nodes.sql; users.sql and teams.sql must have run.
  The executor of a team assignment is a group (UserGroups), of an individual one a user (Users), each by its Guid or Id
  to match the type of Assignments.ExecutorId. Set @CompletedStatusId to the status meaning 'completed' first.
  Replaces the test cases' earlier assignments (@Reset = 1), with their outputs, and removes this organisation's orphaned
  assignments (whose spec no longer exists, as when a case script re-creates its spec). If a spec, node, user or group can't be found, the script
  lists them and writes nothing. Set @Commit = 0 for a dry run.
*/
USE [3b30813b-994f-4bb1-a70f-9763e2b61154];
SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @Commit             bit              = 1;     -- 0 = dry run
DECLARE @Reset              bit              = 1;     -- 1 = replace the test cases' earlier assignments
DECLARE @CompletedStatusId  int              = 3;     -- AssignmentStatuses: 3 = Complete (the stay is over)
DECLARE @OrganisationId     uniqueidentifier = 'DA8BA77A-AE36-43E0-A340-278B76345161';
DECLARE @AuthOrganisationId int              = 12;
DECLARE @ResultId           int              = 45;
DECLARE @CreatedBy          uniqueidentifier = 'A01AE24F-0301-4198-9036-8CC58F070B01';

IF @CompletedStatusId IS NULL
BEGIN
    RAISERROR('Set @CompletedStatusId (the AssignmentStatusId for a completed assignment) first: nothing written.', 16, 1);
    RETURN;
END

DECLARE @rows TABLE (SpecName nvarchar(400), TeamName nvarchar(200), JobName nvarchar(200) NULL,
                     ExecutorEmail nvarchar(256) NULL, ExecutorGroup nvarchar(200) NULL,
                     StartDate datetime2 NULL, CompletionDate datetime2 NULL, ExecutorCount int,
                     SpecId uniqueidentifier NULL, NodeId int NULL, ExecutorGuid uniqueidentifier NULL, ExecutorInt int NULL);

-- The spec, the team or job node, the executor.
UPDATE r SET SpecId = s.Id FROM @rows r
JOIN [Results].dbo.Specs s ON s.Name COLLATE DATABASE_DEFAULT = r.SpecName COLLATE DATABASE_DEFAULT
                         AND s.ResultId = @ResultId AND s.OrganisationId = @OrganisationId;
UPDATE r SET NodeId = CASE WHEN r.JobName IS NULL THEN tn.Id ELSE jn.Id END
FROM @rows r
JOIN [Authorisation].dbo.SkillSets tk ON tk.Name COLLATE DATABASE_DEFAULT = r.TeamName COLLATE DATABASE_DEFAULT
                                     AND tk.NetworkId = 1 AND tk.OrganisationId = @AuthOrganisationId
JOIN dbo.Nodes tn ON tn.SkillSetId = tk.Guid AND tn.NetworkId = 1 AND tn.OrganisationId = @OrganisationId
LEFT JOIN [Authorisation].dbo.SkillSets jk ON jk.Name COLLATE DATABASE_DEFAULT = r.JobName COLLATE DATABASE_DEFAULT
                                          AND jk.NetworkId = 2 AND jk.OrganisationId = @AuthOrganisationId
LEFT JOIN dbo.Nodes jn ON jn.SkillSetId = jk.Guid AND jn.NetworkId = 2 AND jn.ParentNodeId = tn.Id AND jn.OrganisationId = @OrganisationId;
UPDATE r SET ExecutorGuid = u.Guid, ExecutorInt = u.Id FROM @rows r
JOIN [Authorisation].dbo.Users u ON u.Email COLLATE DATABASE_DEFAULT = r.ExecutorEmail COLLATE DATABASE_DEFAULT
                                AND u.OrganisationId = @AuthOrganisationId;
UPDATE r SET ExecutorGuid = g.Guid, ExecutorInt = g.Id FROM @rows r
JOIN [Authorisation].dbo.UserGroups g ON g.Name COLLATE DATABASE_DEFAULT = r.ExecutorGroup COLLATE DATABASE_DEFAULT
                                     AND g.OrganisationId = @AuthOrganisationId;

IF EXISTS (SELECT 1 FROM @rows WHERE SpecId IS NULL OR NodeId IS NULL
           OR (ExecutorGuid IS NULL AND (ExecutorEmail IS NOT NULL OR ExecutorGroup IS NOT NULL)))
BEGIN
    SELECT DISTINCT TOP (50) SpecName, TeamName, JobName, ExecutorEmail, ExecutorGroup,
           CASE WHEN SpecId IS NULL THEN 'spec not found (run the test cases)'
                WHEN NodeId IS NULL THEN 'team or job node not found (run process.sql, job_nodes.sql)'
                ELSE 'user or group not found (run users.sql, teams.sql)' END AS Problem
    FROM @rows WHERE SpecId IS NULL OR NodeId IS NULL OR (ExecutorGuid IS NULL AND (ExecutorEmail IS NOT NULL OR ExecutorGroup IS NOT NULL));
    RAISERROR('Some specs, nodes, users or groups could not be found (see grid): nothing written.', 16, 1);
    RETURN;
END

-- ExecutorId takes a Guid or an Id, whichever its column is.
DECLARE @byGuid bit = CASE WHEN (SELECT t.name FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
                                 WHERE c.object_id = OBJECT_ID('dbo.Assignments') AND c.name = 'ExecutorId') = 'uniqueidentifier'
                           THEN 1 ELSE 0 END;
IF OBJECT_ID('tempdb..#assignment_rows') IS NOT NULL DROP TABLE #assignment_rows;
SELECT * INTO #assignment_rows FROM @rows;

BEGIN TRANSACTION;

-- Reset: the test cases' earlier assignments, and this organisation's orphans (assignments whose spec no longer exists:
-- a spec re-created by a case script gets a new Id), each with its outputs first.
DECLARE @removed int = 0, @orphans int = 0, @outputsRemoved int = 0;
IF @Reset = 1
BEGIN
    IF OBJECT_ID('tempdb..#gone') IS NOT NULL DROP TABLE #gone;
    CREATE TABLE #gone (Id int PRIMARY KEY, Guid uniqueidentifier, Orphan bit);
    SELECT a.Id, a.Guid, CASE WHEN a.SpecId IN (SELECT SpecId FROM #assignment_rows) THEN 0 ELSE 1 END
    FROM dbo.Assignments a
    WHERE a.SpecId IN (SELECT DISTINCT SpecId FROM #assignment_rows)
       OR (a.OrganisationId = @OrganisationId AND NOT EXISTS (SELECT 1 FROM [Results].dbo.Specs s WHERE s.Id = a.SpecId));
    -- What hangs off them, all generated from the data (re-run those scripts after): outputs, materials, readings,
    -- requirements.
    DECLARE @dep sysname, @clear nvarchar(max), @n int;
    DECLARE deps CURSOR LOCAL FAST_FORWARD FOR
        SELECT name FROM (VALUES (N'AssignmentOutputs'), (N'ExecutionMaterials'), (N'ExecutionProperties'),
                                 (N'AssignmentProperties')) d(name)
        WHERE OBJECT_ID(N'dbo.' + name) IS NOT NULL;
    OPEN deps;
    FETCH NEXT FROM deps INTO @dep;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @clear = N'DELETE x FROM dbo.' + QUOTENAME(@dep) + N' x JOIN #gone g ON x.AssignmentId = ' +
            CASE WHEN (SELECT t.name FROM sys.columns c JOIN sys.types t ON t.user_type_id = c.user_type_id
                       WHERE c.object_id = OBJECT_ID(N'dbo.' + @dep) AND c.name = 'AssignmentId') = 'uniqueidentifier'
                 THEN N'g.Guid' ELSE N'g.Id' END + N'; SELECT @n = @@ROWCOUNT;';
        EXEC sp_executesql @clear, N'@n int OUTPUT', @n OUTPUT;
        IF @dep = N'AssignmentOutputs' SET @outputsRemoved = @n;
        FETCH NEXT FROM deps INTO @dep;
    END
    CLOSE deps;
    DEALLOCATE deps;
    DELETE a FROM dbo.Assignments a JOIN #gone g ON g.Id = a.Id;
    SET @removed = @@ROWCOUNT;
    SET @orphans = (SELECT COUNT(*) FROM #gone WHERE Orphan = 1);
    DROP TABLE #gone;
END

DECLARE @insert nvarchar(max) = N'
                             AllOutputsAdded, TaskId, StartDate, Deadline, EstimatedDuration, CompletionDate, CreationDate,
                             ModificationDate, CreatedBy, ModifiedBy)
SELECT NEWID(), r.SpecId, ' + CASE WHEN @byGuid = 1 THEN N'r.ExecutorGuid' ELSE N'r.ExecutorInt' END + N', @OrganisationId, r.NodeId,
       r.ExecutorCount, 1, @CompletedStatusId, 1, NULL, r.StartDate, NULL, NULL, r.CompletionDate, SYSUTCDATETIME(),
       NULL, @CreatedBy, NULL
FROM #assignment_rows r;
SELECT @added = @@ROWCOUNT;';
DECLARE @added int = 0;
EXEC sp_executesql @insert, N'@OrganisationId uniqueidentifier, @CompletedStatusId int, @CreatedBy uniqueidentifier, @added int OUTPUT',
                   @OrganisationId, @CompletedStatusId, @CreatedBy, @added OUTPUT;

SELECT @removed AS AssignmentsRemoved, @orphans AS OfWhichOrphans, @outputsRemoved AS OutputsRemoved, @added AS AssignmentsAdded,
       (SELECT COUNT(*) FROM #assignment_rows WHERE JobName IS NULL) AS TeamAssignments,
       (SELECT COUNT(*) FROM #assignment_rows WHERE JobName IS NOT NULL) AS IndividualAssignments;
DROP TABLE #assignment_rows;

IF @Commit = 1 BEGIN COMMIT TRANSACTION;   PRINT 'Committed.'; END
ELSE           BEGIN ROLLBACK TRANSACTION; PRINT 'Dry run: rolled back.'; END
